update plan_projects set story = $story${"plan_number": "תמל/1062", "official_name": "קריית פארק לכיש - אשדוד", "kicker": "צפון אשדוד · בין נחל לכיש לרחוב הרצל, מצפון לרובע א'", "headline": "שכונה חדשה ליד פארק נחל לכיש", "headline_serif": "פארק נחל לכיש", "deck": "על כ-617 דונם, רובם פנויים, מתוכננת שכונה של 3,008 דירות, מתוכן 240 בדיור מוגן, עם קריית ספורט ואצטדיון כדורגל, מסחר ותעסוקה, מוסדות ציבור וחלק מפארק נחל לכיש.", "status": {"label": "מאושרת, והבנייה התחילה", "text": "התוכנית אושרה בוועדה הארצית למתחמים מועדפים לדיור (ותמ\"ל). ההוראות והתשריטים שבידינו הם הנוסח מ-23 ביולי 2018. לפי מפת OpenStreetMap, ב-2026 כבר עומדים בניינים חדשים בחלק ממגרשי המגורים בדרום התוכנית.", "source": "אישור התוכנית: לפי ענת שטיבלמן, 19.11.2026; הוראות התכנית, מועד הפקה 23/07/2018; OpenStreetMap (הערכה)"}, "chapters": [{"id": "headline", "title": "במשפט אחד", "lead": "שכונה חדשה על קרקע פנויה, בין העיר לנחל לכיש.", "paragraphs": ["התוכנית חלה על 617 דונם בצפון אשדוד, ממזרח לנמל, בין נחל לכיש ממערב לרחוב הרצל ממזרח ומצפון לרובע א'.", "היא מתכננת 3,008 דירות, מהן 240 בדיור מוגן לגיל הזהב, כ-80,000 מ\"ר למסחר ולתעסוקה, קריית ספורט עם אצטדיון כדורגל לכ-24,000 צופים, היכל ספורט לכ-5,000 צופים ובריכת שחייה, מבני ציבור ופארק."], "sources": ["דברי הסבר", "סעיף 1.2", "סעיף 1.5.2", "סעיף 2.1"]}, {"id": "why", "title": "למה", "lead": "דיור חדש בקרקע של המדינה, ופתיחת פארק הנחל לעיר.", "paragraphs": ["התוכנית היא תוכנית מועדפת לדיור, לפי החוק לקידום הבנייה במתחמים מועדפים לדיור (הוראת שעה, 2014). מגישה אותה רשות מקרקעי ישראל, והקרקע של המדינה ושל עיריית אשדוד.", "לפי דברי ההסבר, היא רוצה ליצור שכונה עם שימושים מעורבים, לפתוח את פארק נחל לכיש לתושבי השכונה והעיר, ליצור דופן עירונית לרחוב הרצל ולפתח את קריית הספורט כמרחב עירוני פעיל."], "sources": ["עמ' 1", "דברי הסבר", "סעיף 1.8"]}, {"id": "before", "title": "לפני", "lead": "שטח פנוי ברובו, חלק מפארק נחל לכיש ורצועה לאורך מסילת הרכבת.", "paragraphs": ["לפי דברי ההסבר, שטח התוכנית פנוי ברובו מבנייה. היא כוללת חלק מפארק נחל לכיש, ושומרת על ערכי הטבע והנוף שבו.", "בתשריט מסומנים מבנים להריסה רק בארבעה מקומות: במגרש המגורים 10, במגרש האימונים 601, באתר תחנת השאיבה 707 ובדרך 1001.", "רצועה של כ-35 דונם לאורך מסילת הברזל (תא שטח 995) נשארת לפי תוכנית מאושרת אחרת. לפי ההוראות יוקם בה מתרס אקוסטי."], "facts": [{"value": "617.4", "unit": "דונם", "label": "שטח התוכנית", "certainty": "plan"}, {"value": "0", "unit": "דירות", "label": "יש היום בשטח, לפי דברי ההסבר (השטח פנוי ברובו)", "certainty": "plan"}], "sources": ["דברי הסבר", "סעיף 1.2", "טבלה 3.1, מבנה להריסה", "סעיף 4.14", "טבלה 3.2"]}, {"id": "after", "title": "אחרי", "lead": "בנייה מרקמית של 7 עד 9 קומות, 11 מגדלים, קריית ספורט ופארק.", "paragraphs": ["רוב בנייני המגורים יהיו בבנייה מרקמית של 7 עד 9 קומות. בנוסף יהיו 11 מגדלי מגורים של 17 עד 29 קומות. ברחובות המסחריים (תאי שטח 16, 17, 18, 27, 29 ו-31) תהיה קומת מסחר בקומת הקרקע, בגובה 4 מטרים לפחות.", "בתא שטח 28 ייבנה בית לגיל הזהב: 240 דירות דיור מוגן, עד 9 קומות, עם חזית מסחרית.", "במגרשי המסחר והתעסוקה (501 עד 504) יהיו שני בנייני משרדים של 15 קומות ליד קריית הספורט, ובניינים של 5 עד 6 קומות ליד הפארק. בתא שטח 501 יהיו גם 300 מקומות חניה תת-קרקעיים לקריית הספורט.", "בתא שטח 600 (כ-83 דונם) ייבנו אצטדיון כדורגל בכיוון צפון-דרום, היכל ספורט ובריכת שחייה. בין רחוב הרצל לפארק יעברו דרכו מעברים פתוחים לציבור ברוחב 10 מטרים לפחות.", "בדגם התלת-ממדי, המעטפת היא השטח שבין קווי הבניין בתשריט, עד מספר הקומות בטבלה 5. הגובה (3.3 מטרים לקומה) והבניין שבתוך המעטפת הם הערכה. האצטדיון מוצג כנפח אחד של 5 קומות, כי צורתו אינה קבועה בתוכנית."], "sources": ["דברי הסבר", "סעיף 4.1", "סעיף 4.2", "סעיף 4.3", "סעיף 4.7", "טבלה 5"]}, {"id": "numbers", "title": "במספרים", "lead": "המספרים העיקריים מטבלה 5 ומהוראות התוכנית.", "facts": [{"value": "3,008", "unit": "דירות", "label": "בתוכנית, לפי סעיף 2.1 וטבלה 5", "certainty": "plan"}, {"value": "240", "unit": "דירות", "label": "דיור מוגן לגיל הזהב (תא שטח 28)", "certainty": "plan"}, {"value": "25%", "unit": "", "label": "מהדירות יהיו קטנות, 30 עד 80 מ\"ר", "certainty": "plan"}, {"value": "29", "unit": "דירות לדונם", "label": "צפיפות ממוצעת נטו", "certainty": "plan"}, {"value": "29", "unit": "קומות", "label": "הבניין הגבוה ביותר", "certainty": "plan"}, {"value": "79,865", "unit": "מ\"ר", "label": "שטח עיקרי למסחר ולתעסוקה (סכום טבלה 5; בדברי ההסבר: כ-80,000)", "certainty": "plan"}, {"value": "174,785", "unit": "מ\"ר", "label": "שטח עיקרי למבני ציבור (סכום טבלה 5)", "certainty": "plan"}, {"value": "122.7", "unit": "דונם", "label": "פארק וגן ציבורי, ועוד 23.2 דונם שצ\"פ", "certainty": "plan"}], "sources": ["סעיף 2.1", "סעיף 1.9", "סעיף 4.1, תמהיל", "דברי הסבר", "טבלה 5", "טבלה 3.2"]}, {"id": "gets", "title": "מה השכונה מקבלת", "lead": "בתי ספר, מבני ציבור, קריית ספורט ופארק נחל.", "bullets": ["שישה מגרשים למבני ציבור, כ-58 דונם. מגרשים 200 ו-205 מיועדים בעיקר לחינוך, ומגרשי הספורט של בתי הספר יהיו פתוחים לציבור כשבית הספר סגור.", "קריית ספורט: אצטדיון כדורגל לכ-24,000 צופים, היכל ספורט לכ-5,000 צופים, בריכת שחייה ומגרשי אימונים (תאי שטח 600 ו-601).", "פארק נחל לכיש: כ-123 דונם של פארק. לאורך הנחל (תאי שטח 2001 ו-2002) פארק טבעי שמשמש מסדרון אקולוגי, בליווי אקולוג.", "שתי כיכרות עירוניות עם חזית מסחרית, שבילי הולכי רגל ואופניים, ומסוף אוטובוסים (תא שטח 800).", "כל רשתות החשמל והתקשורת יהיו תת-קרקעיות."], "sources": ["סעיף 4.4", "סעיף 4.6", "סעיף 4.7", "סעיף 4.8", "סעיף 4.9", "סעיף 6.16", "טבלה 3.2"]}, {"id": "me", "title": "מה משתנה לי", "lead": "תלוי איפה גרים.", "bullets": ["גרים ברובע א' או ליד רחוב הרצל: שכונה חדשה ממערב לרחוב, עם חיבורי תנועה לרחוב הרצל ולרובע א'.", "משתמשים בפארק נחל לכיש: הפארק יפותח ברצף אחד, עם כניסות מהשכונה, טיילת לאורך הנחל ותאורה מוגבלת לאורכו.", "באים למשחקים: לפני היתר לאצטדיון צריך תוכנית לניהול תנועה וחניה בזמן אירועים, ואמצעים למניעת מטרדים לשכונות.", "גרים ליד מסילת הרכבת או הנמל: לפני אכלוס הבניינים במגרשים 25 ו-26 צריך לבנות קיר אקוסטי ליד המסילה."], "sources": ["דברי הסבר", "סעיף 6.2", "סעיף 4.7.2", "סעיף 6.4, 10", "סעיף 6.5 ב"]}, {"id": "weigh", "title": "השקילה", "lead": "שכונה גדולה ליד פארק, מול רעש, אצטדיון והגנה על הנחל.", "draft": true, "pros": ["3,008 דירות חדשות על קרקע פנויה, בלי לפנות דיירים.", "רבע מהדירות קטנות, ויש דיור מוגן לגיל הזהב.", "פארק נחל לכיש נפתח לעיר, עם הגנה על הנחל כמסדרון אקולוגי.", "קריית ספורט ומבני ציבור גדולים."], "questions": ["השכונה סמוכה לנמל, למסילת הרכבת ולתחנת מיון הרכבות. האם המיגון האקוסטי יספיק?", "מה יהיה העומס בתנועה ובחניה בימי משחק באצטדיון?", "איך תישמר הרציפות האקולוגית של הנחל ליד שכונה של 3,000 דירות?", "מגדלים של 29 קומות ליד הפארק: איך ישפיעו על הצל בפארק ובמבני הציבור?"], "sources": ["סעיף 6.5", "סעיף 6.4", "סעיף 4.6", "טבלה 5"]}, {"id": "path", "title": "הדרך לביצוע", "lead": "תוכנית בינוי, היתרים, ומגורים יחד עם התשתיות.", "steps": [{"title": "אישור התוכנית", "text": "אושרה בוועדה הארצית למתחמים מועדפים לדיור. הבנייה במגרשי המגורים בדרום התוכנית כבר התחילה."}, {"title": "תוכנית בינוי ופיתוח", "text": "תנאי להיתר הראשון: הוועדה המקומית מאשרת תוכנית בינוי ופיתוח בקנה מידה 1:500, לכל השטח או לחלקים ממנו."}, {"title": "היתרים", "text": "לפני כל היתר: מיגון אקוסטי לפי הנספח האקוסטי, אישור המשרד להגנת הסביבה בעניין חומרים מסוכנים, פתרון ביוב ואישור רשות המים לשאיבת מי תהום."}, {"title": "מגורים יחד עם תשתיות", "text": "המגורים ייבנו בד בבד עם התשתיות, מוסדות הציבור והשטחים הפתוחים."}, {"title": "מועד", "text": "משך הביצוע הצפוי הוא 15 שנה."}], "sources": ["סעיף 6.4", "סעיף 6.5", "סעיף 7.1", "סעיף 7.2"]}, {"id": "glossary", "title": "מילון קצר", "terms": [{"term": "תוכנית מועדפת לדיור (תמ\"ל)", "def": "תוכנית לבנייה רחבה של דירות, שמאשרת ועדה ארצית מיוחדת (ותמ\"ל) לפי חוק זמני מ-2014, כדי לקצר את התכנון."}, {"term": "דיור מוגן", "def": "דירות לאנשים מבוגרים עם שירותים משותפים, לפי חוק הדיור המוגן."}, {"term": "בנייה מרקמית", "def": "בניינים בגובה בינוני שעומדים קרוב לרחוב ויוצרים רחוב רציף."}, {"term": "דירה קטנה", "def": "לפי התוכנית: דירה ששטחה העיקרי 30 עד 80 מ\"ר, כולל ממ\"ד."}, {"term": "מסדרון אקולוגי", "def": "רצועה של שטח טבעי שמאפשרת לבעלי חיים ולצמחים לעבור ולהתקיים."}, {"term": "שצ\"פ", "def": "שטח ציבורי פתוח: גינה, שביל או כיכר לשימוש כולם."}]}], "disclaimer": "העמוד מסביר את התוכנית בשפה פשוטה. המסמכים המחייבים הם מסמכי התוכנית באתר תכנון זמין. מספרים שמסומנים \"הערכה\" חושבו או נקראו לצורך ההסבר.", "reviewed": false, "level": "full"}$story$::jsonb where plan_number = 'תמל/1062';
